package main

import (
	"crypto/subtle"
	"encoding/base64"
	"fmt"
	"net"
	"net/http"
	"net/url"
	"strings"
	"sync"
)

type Role int

const (
	RoleGuest Role = iota
	RoleUser
	RoleAdmin
)

type Session struct {
	Username string
	Role     Role
	Token    string
}

var (
	sessions   = make(map[string]*Session)
	sessionsMu sync.RWMutex
	allowedDomains = []string{"internal.corp.net", "dashboard.corp.net", "api.corp.net"}
)

func init() {
	sessions["admin-token-xyz"] = &Session{Username: "admin", Role: RoleAdmin, Token: "admin-token-xyz"}
	sessions["user-token-abc"] = &Session{Username: "jdoe", Role: RoleUser, Token: "user-token-abc"}
}

func getSession(r *http.Request) *Session {
	token := r.Header.Get("X-Auth-Token")
	if token == "" {
		if cookie, err := r.Cookie("session"); err == nil {
			token = cookie.Value
		}
	}
	sessionsMu.RLock()
	defer sessionsMu.RUnlock()
	return sessions[token]
}

func requireRole(minRole Role, handler http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		sess := getSession(r)
		if sess == nil {
			http.Error(w, "Unauthorized", http.StatusUnauthorized)
			return
		}
		if sess.Role < minRole {
			http.Error(w, "Forbidden", http.StatusForbidden)
			return
		}
		handler(w, r)
	}
}

func resolveDNS(domain string) (string, error) {
	ips, err := net.LookupHost(domain)
	if err != nil {
		return "", err
	}
	if len(ips) == 0 {
		return "", fmt.Errorf("no IPs found for %s", domain)
	}
	return ips[0], nil
}

func isDomainAllowed(target string) bool {
	for _, allowed := range allowedDomains {
		if subtle.ConstantTimeCompare([]byte(target), []byte(allowed)) == 1 {
			return true
		}
	}
	return false
}

func normalizeRedirectTarget(rawTarget string) (string, error) {
	decoded, err := base64.RawURLEncoding.DecodeString(rawTarget)
	if err != nil {
		decoded = []byte(rawTarget)
	}
	target := string(decoded)
	if !strings.Contains(target, "://") {
		target = "https://" + target
	}
	parsed, err := url.Parse(target)
	if err != nil {
		return "", err
	}
	return parsed.String(), nil
}

func validateRedirectHost(fullURL string) (string, bool) {
	parsed, err := url.Parse(fullURL)
	if err != nil {
		return "", false
	}
	host := parsed.Hostname()
	if isDomainAllowed(host) {
		return fullURL, true
	}
	return "", false
}

func handleResolveAndRedirect(w http.ResponseWriter, r *http.Request) {
	rawTarget := r.URL.Query().Get("target")
	if rawTarget == "" {
		http.Error(w, "missing target parameter", http.StatusBadRequest)
		return
	}

	normalized, err := normalizeRedirectTarget(rawTarget)
	if err != nil {
		http.Error(w, "invalid target", http.StatusBadRequest)
		return
	}

	validated, ok := validateRedirectHost(normalized)
	if !ok {
		http.Error(w, "target not in allowed list", http.StatusForbidden)
		return
	}

	http.Redirect(w, r, validated, http.StatusFound)
}

func handleDNSLookup(w http.ResponseWriter, r *http.Request) {
	domain := r.URL.Query().Get("domain")
	if domain == "" {
		http.Error(w, "missing domain", http.StatusBadRequest)
		return
	}
	if !isDomainAllowed(domain) {
		http.Error(w, "domain not allowed", http.StatusForbidden)
		return
	}
	ip, err := resolveDNS(domain)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, `{"domain":"%s","ip":"%s"}`, domain, ip)
}

func main() {
	http.HandleFunc("/dns/lookup", requireRole(RoleUser, handleDNSLookup))
	http.HandleFunc("/dns/redirect", requireRole(RoleAdmin, handleResolveAndRedirect))
	http.ListenAndServe(":8443", nil)
}
